patch:
diff --git a/native/Sources/NTSDRuntime/OriginalMacDisplayBackend.swift b/native/Sources/NTSDRuntime/OriginalMacDisplayBackend.swift
index dee1726..84d6078 100644
--- a/native/Sources/NTSDRuntime/OriginalMacDisplayBackend.swift
+++ b/native/Sources/NTSDRuntime/OriginalMacDisplayBackend.swift
@@ -1320,6 +1320,7 @@ extension OriginalMacDisplayBackend {
             // (MOBILE_PERFORMANCE steps 4-5). Same pixels and bits; the
             // loop never reads the target's mask.
             let keyed = copy.key != nil,low = copy.key?[0] ?? 0,high = copy.key?[1] ?? 0,step = copy.mirrored ? -1 : 1
+            let separate = input !== output
             let width = rect.right-rect.left
             for y in rect.top..<rect.bottom {
                 var a = copy.sourceIndex(rect.left,y),b = y*output.width+rect.left
@@ -1339,14 +1340,44 @@ extension OriginalMacDisplayBackend {
                     // and the store alone (the live app's targets are always
                     // full; on the A12 40% less time per keyed sprite pixel;
                     // CORE_REALTIME 1j).
+                    // Four pixels at a time where the surfaces differ (no
+                    // overlap, so reading four sources before writing four
+                    // targets is the scalar order's result): the same key test
+                    // per lane, and a lane the key rejects is stored back
+                    // unchanged (CORE_REALTIME R4). The rest of the row, and
+                    // every copy within one surface, stays scalar.
+                    var done = 0
+                    #if _endian(little)
+                    if separate && width >= 4 {
+                        let source = UnsafeRawPointer(inputValues),target = UnsafeMutableRawPointer(outputValues)
+                        let rgb = SIMD4<UInt32>(repeating:0xffffff),below = SIMD4<UInt32>(repeating:low),above = SIMD4<UInt32>(repeating:high)
+                        while done+4 <= width {
+                            let pixels: SIMD4<UInt32>
+                            if step > 0 { pixels = source.loadUnaligned(fromByteOffset:a*4,as:SIMD4<UInt32>.self) }
+                            else {
+                                let r = source.loadUnaligned(fromByteOffset:(a-3)*4,as:SIMD4<UInt32>.self)
+                                pixels = SIMD4(r[3],r[2],r[1],r[0])
+                            }
+                            if keyed {
+                                let value = pixels & rgb,take = (value .< below) .| (value .> above)
+                                let old = target.loadUnaligned(fromByteOffset:b*4,as:SIMD4<UInt32>.self)
+                                target.storeBytes(of:old.replacing(with:pixels,where:take),toByteOffset:b*4,as:SIMD4<UInt32>.self)
+                            } else {
+                                // Mirrored only: a forward unkeyed known row took the row copy above.
+                                target.storeBytes(of:pixels,toByteOffset:b*4,as:SIMD4<UInt32>.self)
+                            }
+                            a += 4*step;b += 4;done += 4
+                        }
+                    }
+                    #endif
                     if keyed {
-                        for _ in 0..<width {
+                        for _ in done..<width {
                             let pixel = inputValues[a],value = UInt32(littleEndian:pixel) & 0xffffff
                             if value < low || value > high { outputValues[b] = pixel }
                             a += step;b += 1
                         }
                     } else {
-                        for _ in 0..<width { outputValues[b] = inputValues[a];a += step;b += 1 }
+                        for _ in done..<width { outputValues[b] = inputValues[a];a += step;b += 1 }
                     }
                     continue
                 }
